const {execFileSync, execFile} = require('child_process');
const EXE = '/workspace/dataset/test15_executable';
const NUL = String.fromCharCode(0);

// 1. Can a NUL byte reach args.a at all?
const nulCases = [NUL, 'A' + NUL + 'B', NUL + 'A'];
for (const s of nulCases) {
  try {
    const o = execFileSync(EXE, ['--a', s, '--b', '1', '--c', '1', '--d', '1'], {encoding: 'utf8'});
    console.log('argv=' + JSON.stringify(s), '-> line0 =', JSON.stringify(o.split('\n')[0]));
  } catch (e) {
    console.log('argv=' + JSON.stringify(s), '-> THREW status=' + e.status,
      'msg=' + String(e.message).split('\n')[0].slice(0, 140));
  }
}

// 2. Does any reachable output ever start with '1'?
const cases = [];
for (let i = 1; i <= 127; i++) { const c = String.fromCharCode(i); if (c !== '-') cases.push(c); }
for (let i = 1; i <= 80; i++) { const c = String.fromCharCode(i) + String.fromCharCode(i); if (!c.startsWith('-')) cases.push(c); }
for (let cp = 0x80; cp < 0x900; cp += 3) cases.push(String.fromCodePoint(cp));
let idx = 0, done = 0, hits = 0;
function next() {
  if (idx >= cases.length) return;
  const s = cases[idx++];
  execFile(EXE, ['--a', s, '--b', '1', '--c', '1', '--d', '1'], {encoding: 'utf8'}, (e, so) => {
    const l = (so || '').split('\n')[0];
    if (/^b'1/.test(l)) { hits++; console.log("starts with '1':", JSON.stringify(s), l); }
    done++;
    if (done === cases.length) console.log('scanned=' + cases.length + " outputs_starting_with_1=" + hits);
    else next();
  });
}
for (let k = 0; k < 24; k++) next();

